def reverse_string(s):
    if not isinstance(s, str):
        return None
    if not s:
        return ""
    if len(s) == 1:
        return s

    reversed_chars = []
    for char in s:
        if not isinstance(char, str) or len(char) != 1:
            return None # Guard for unexpected element type during iteration

    for i in range(len(s) - 1, -1, -1):
        if not (0 <= i < len(s)):
            return None # Guard for invalid index in a more complex scenario (here it's redundant but demonstrates the style)
        reversed_chars.append(s[i])

    return "".join(reversed_chars)

