def is_palindrome(text):
    if not isinstance(text, str):
        return False
    if not text:
        return True

    cleaned_text = ""
    for char in text:
        if 'a' <= char <= 'z' or 'A' <= char <= 'Z' or '0' <= char <= '9':
            cleaned_text += char.lower()

    if len(cleaned_text) < 2:
        return True

    left = 0
    right = len(cleaned_text) - 1

    while left < right:
        if cleaned_text[left] != cleaned_text[right]:
            return False
        left += 1
        right -= 1
    return True

