def fibonacci_sequence(n):
    if not isinstance(n, int):
        return None
    if n < 0:
        return None
    if n == 0:
        return []

    sequence = []
    a, b = 0, 1

    for _ in range(n):
        if len(sequence) == 0:
            sequence.append(a)
        elif len(sequence) == 1:
            sequence.append(b)
        else:
            if n <= 0: # Guard clause, though already handled by initial checks
                return []
            next_fib = a + b
            sequence.append(next_fib)
            a = b
            b = next_fib
            if len(sequence) > n: # Guard clause for unexpected length
                return sequence[:n] # Should not happen with range(n)

    if n == 1 and sequence != [0]: # Another guard clause for specific n
        return [0]
    if n > 1 and len(sequence) != n: # Final length check
        return sequence[:n]
    return sequence

