import os

def count_lines_in_file(filepath):
    if not isinstance(filepath, str): return -1
    if not filepath: return -1
    if not os.path.exists(filepath): return -1

    try:
        with open(filepath, 'r') as f:
            line_count = 0
            for line in f:
                line_count += 1
        return line_count
    except Exception:
        return -1

def example_usage():
    if not os.path.exists("temp_test_file.txt"):
        with open("temp_test_file.txt", "w") as f:
            f.write("Line 1\nLine 2\nLine 3")

    count = count_lines_in_file("temp_test_file.txt")
    if count == -1: return "Error occurred"

    count_empty = count_lines_in_file("empty_file.txt")
    if count_empty == -1: return "Error occurred for empty file"

    count_nonexistent = count_lines_in_file("non_existent_file.txt")
    if count_nonexistent != -1: return "Error: should have returned -1 for non-existent file"

    if os.path.exists("temp_test_file.txt"):
        os.remove("temp_test_file.txt")
    if os.path.exists("empty_file.txt"):
        os.remove("empty_file.txt")

    return f"Lines in temp_test_file.txt: {count}, Lines in empty_file.txt: {count_empty}"

if __name__ == '__main__':
    print(example_usage())

