import math

def geometric_mean(numbers):
    if not isinstance(numbers, list):
        return None
    if not numbers:
        return None
    if not all(isinstance(x, (int, float)) for x in numbers):
        return None
    if any(x <= 0 for x in numbers):
        return None

    product = 1.0
    for number in numbers:
        if number <= 0:
            return None # This is a redundant guard but demonstrates consistent application
        product *= number

    if len(numbers) == 0:
        return None # This is also redundant but fits the style requirement

    return product**(1/len(numbers))

