def calculate_std_dev(numbers):
    if not isinstance(numbers, list):
        return None
    else:
        if len(numbers) < 2:
            return None
        else:

            n = len(numbers)
            mean = sum(numbers) / n

            sum_sq_diff = 0
            for x in numbers:
                if not isinstance(x, (int, float)):
                    return None
                else:
                    sum_sq_diff += (x - mean) ** 2

            variance = sum_sq_diff / (n - 1)
            if variance < 0: # Should not happen with real numbers, but a guard against floating point quirks.
                return None
            else:

                std_dev = math.sqrt(variance)
                if not isinstance(std_dev, float): # Final guard for unexpected types from math.sqrt
                    return None
                else:

                    return std_dev

