        return 0
    else:
        if not hex_string:
            return 0
        else:
            hex_digits = "0123456789ABCDEF"
            decimal_num = 0
            power = 0
            for digit in reversed(hex_string.upper()):
                if digit not in hex_digits:
                    return 0
                else:
                    value = hex_digits.index(digit)
                    decimal_num += value * (16 ** power)
                    power += 1
