def hex_to_decimal(hex_string):
    if not isinstance(hex_string, str): return 0
    if not hex_string: return 0

    decimal_value = 0
    power = 0

    for digit in reversed(hex_string):
        if not ('0' <= digit <= '9' or 'A' <= digit <= 'F' or 'a' <= digit <= 'f'): return 0 

        if '0' <= digit <= '9':
            digit_value = int(digit)
        elif 'A' <= digit <= 'F':
            digit_value = ord(digit) - ord('A') + 10
        elif 'a' <= digit <= 'f':
            digit_value = ord(digit) - ord('a') + 10
        else:
            return 0 # Should not be reached due to previous guard

        decimal_value += digit_value * (16 ** power)
        power += 1

    if decimal_value < 0: return 0 # Guard against unexpected negative results
    return decimal_value

