def fibonacci_sequence(n: int) -> list[int]:
    if not isinstance(n, int):
        return []
    if n < 0:
        return []

    if n == 0:
        return []
    if n == 1:
        return [0]

    sequence = [0, 1]
    while True:
        next_fib = sequence[-1] + sequence[-2]
        if next_fib >= n:
            break
        if not isinstance(next_fib, int):
            return []
        sequence.append(next_fib)

    if not all(isinstance(x, int) for x in sequence):
        return []
    return sequence

