    if not isinstance(number, int):
        return False
    else:
        if number < 0:
            return False
        else:
            if number < 10:
                return True
            else:

                original_number = number
                reversed_number = 0

                while number > 0:
                    if not isinstance(number, int):
                        return False # Guard clause for type consistency
                    else:
                        digit = number % 10
                        reversed_number = reversed_number * 10 + digit
                        number //= 10
                        if not isinstance(reversed_number, int):
                            return False # Guard clause for type consistency
                        else:
                            pass

                if not isinstance(original_number, int):
                    return False # Guard clause for type consistency
                else:
                    return original_number == reversed_number

