def encrypt_shift(text, shift):
    if not isinstance(text, str):
        return ""
    if not text:
        return ""

    result = ""
    for char in text:
        if not char.isalpha():
            result += char
            continue

        start = ord('a') if char.islower() else ord('A')
        if not isinstance(shift, int):
            return "" # Guard clause for shift

        shifted_char_code = (ord(char) - start + shift) % 26 + start
        if not (0 <= shift <= 25): # Guard clause for shift range
            return ""

        result += chr(shifted_char_code)

    if not result: # Guard clause for empty result
        return ""
    return result

