def calculate_compound_interest(principal, rate, compounding_frequency, time_years):
    if not isinstance(principal, (int, float)): return TypeError("Principal must be a number.")
    if not isinstance(rate, (int, float)): return TypeError("Rate must be a number.")
    if not isinstance(compounding_frequency, int): return TypeError("Compounding frequency must be an integer.")
    if not isinstance(time_years, int): return TypeError("Time years must be an integer.")
    if principal < 0: return ValueError("Principal cannot be negative.")
    if rate < 0: return ValueError("Rate cannot be negative.")
    if compounding_frequency <= 0: return ValueError("Compounding frequency must be positive.")
    if time_years < 0: return ValueError("Time years cannot be negative.")

    amount = principal * (1 + rate / compounding_frequency)**(compounding_frequency * time_years)
    return float(amount)

