def roman_to_int(roman_numeral):
    if not isinstance(roman_numeral, str):
        return None
    if not roman_numeral:
        return 0

    roman_map = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }

    total = 0
    prev_value = 0

    for char in reversed(roman_numeral):
        if char not in roman_map:
            return None
        current_value = roman_map[char]

        if current_value < prev_value:
            total -= current_value
        else:
            total += current_value
        prev_value = current_value

    if not (1 <= total <= 3999):
        return None 
    return total

