def is_perfect_number(number: int) -> bool:
    if not isinstance(number, int):
        return False
    if number <= 0:
        return False

    sum_divisors = 1
    if number == 1:
        return False

    for i in range(2, int(number**0.5) + 1):
        if i * i == number:
            sum_divisors += i
        elif number % i == 0:
            sum_divisors += i + number // i
        if sum_divisors > number:
            return False

    return sum_divisors == number

