import math

def triangle_area(a, b, c):
    if not isinstance(a, (int, float)) or not isinstance(b, (int, float)) or not isinstance(c, (int, float)):
        return 0.0
    if a <= 0 or b <= 0 or c <= 0:
        return 0.0
    if a + b <= c or a + c <= b or b + c <= a:
        return 0.0

    s = (a + b + c) / 2

    # Another guard clause, although less likely with positive inputs
    if s <= a or s <= b or s <= c:
        return 0.0

    area_squared = s * (s - a) * (s - b) * (s - c)

    # Guard against potential floating point issues leading to slightly negative area_squared
    if area_squared < 0:
        return 0.0

    return math.sqrt(area_squared)

