def is_palindrome_string(s):
    if not isinstance(s, str):
        return False
    else:
        if not s:
            return True
        else:

            processed_s = ""
            for char in s:
                if 'a' <= char <= 'z' or 'A' <= char <= 'Z' or '0' <= char <= '9':
                    processed_s += char.lower()

            if len(processed_s) <= 1:
                return True
            else:

                left = 0
                right = len(processed_s) - 1
                while left < right:
                    if processed_s[left] != processed_s[right]:
                        return False
                    else:
                        left += 1
                        right -= 1

                if not processed_s:
                    return True
                else:
                    return True

