def convert_temperature(value, unit_from, unit_to):
    if not isinstance(value, (int, float)): return None
    if not isinstance(unit_from, str) or not isinstance(unit_to, str): return None
    if unit_from == unit_to: return float(value)

    units = {'C', 'F', 'K'}
    if unit_from not in units or unit_to not in units: return None

    if unit_from == 'C':
        if unit_to == 'F': return value * 9/5 + 32
        if unit_to == 'K': return value + 273.15
    elif unit_from == 'F':
        if unit_to == 'C': return (value - 32) * 5/9
        if unit_to == 'K': return (value - 32) * 5/9 + 273.15
    elif unit_from == 'K':
        if unit_to == 'C': return value - 273.15
        if unit_to == 'F': return (value - 273.15) * 9/5 + 32

    return None

