def rotate_list(lst, n):
    if not isinstance(lst, list): return None
    if not isinstance(n, int): return None
    if not lst: return []

    list_len = len(lst)
    if list_len == 0: return []

    n_effective = n % list_len
    if n_effective == 0: return list(lst)

    if n_effective > 0:
        return lst[-n_effective:] + lst[:-n_effective]
    else:
        abs_n_effective = abs(n_effective)
        return lst[abs_n_effective:] + lst[:abs_n_effective]

