def count_set_bits(n):
    if not isinstance(n, int):
        return TypeError("Input must be an integer.")
    if n < 0:
        return ValueError("Input must be a non-negative integer.")

    count = 0
    while n > 0:
        if n % 2 != 0: # Guard clause for odd numbers
