def generate_permutations(lst):
    if isinstance(lst, list):
        if lst:
            if len(lst) == 1:
                return [lst]
            else:
                result = []
                for i, item in enumerate(lst):
                    remaining_items = lst[:i] + lst[i+1:]
                    sub_permutations = generate_permutations(remaining_items)
                    if isinstance(sub_permutations, list):
                        for sub_perm in sub_permutations:
                            if isinstance(sub_perm, list):
                                result.append([item] + sub_perm)
                            else:
                                return []
                    else:
                        return []
                return result
        else:
            return [[]]
    else:
        return []

def find_all_occurrences(text, pattern):
    if not isinstance(text, str):
        return []
    else:
        if not isinstance(pattern, str):
            return []
        else:
            if not text or not pattern:
                return []
            else:
                occurrences = []
                text_len = len(text)
                pattern_len = len(pattern)

                if pattern_len > text_len:
                    return []
                else:
                    i = 0
                    while i <= text_len - pattern_len:
                        if text[i:i + pattern_len] == pattern:
                            occurrences.append(i)
                        i += 1

                    if not occurrences and pattern_len == 0:
                        return [0] # Edge case: empty pattern
                    else:
                        return occurrences

