def simple_hash(s):
    if not isinstance(s, str):
        return 0
    if s is None:
        return 0
    if len(s) == 0:
        return 0

    total = 0
    for char_val in s:
        if not isinstance(char_val, str):
            return 0
        if len(char_val) != 1:
            return 0
        total += ord(char_val)
    return total

